arguments.new_string:
        if errs:
            # TODO: due to the usage of basic path (not a Path
            # object), the format can be a bit inconsistent here
            # (e.g., 'a.b' and ['a', 'b'])
            raise CheckError(errs, self, scope[Path])
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        args = []
        if self.spec is not T:
            args.append('spec=%r' % self.spec)
        if self.types:
            args.append('type=%r' % list(self.types))
        if self.vals:
            args.append('equal_to=%r' % self.vals[0] if len(self.vals) == 1 else 'one_of=%r' % list(self.vals))
        if self.validators:
            args.append('validate=%r' % [getattr(v, '__name__', v) for v in self.validators])
        if self.instance_of:
            args.append('instance_of=%r' % list(self.instance_of))
        if self.default is not RAISE:
            args.append('default=%r' % self.default)
        return '%s(%s)' % (cn, ', '.join(args))


